@@ -0,0 +1,16 @@
+import { createEventCard } from './event-card.js';
+
+export function buildAgenda(events) {
+  return sortEventsChronologically(events).map(createEventCard);
+}
+
+export function sortEventsChronologically(events) {
+  return events
+    .map((event, index) => ({ event, index, card: createEventCard(event) }))
+    .sort((a, b) => timestamp(a.event) - timestamp(b.event) || a.index - b.index)
+    .map(({ event }) => event);
+}
+
+function timestamp(event) {
+  return new Date(event.startsAt).getTime();
+}

